// Polls a Server + its most recent Job until terminal state or timeout.
// Usage: npx tsx poll.ts <serverId> <jobId> [timeoutMinutes]
import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();

async function main() {
  const serverId = process.argv[2];
  const jobId = process.argv[3];
  const timeoutMin = Number(process.argv[4] ?? 30);
  const deadline = Date.now() + timeoutMin * 60_000;

  while (Date.now() < deadline) {
    const [server, job] = await Promise.all([
      db.server.findUnique({ where: { id: serverId } }),
      db.job.findUnique({ where: { id: jobId } }),
    ]);
    const ts = new Date().toISOString();
    console.log(
      `${ts} server.status=${server?.status} vmid=${server?.vmid} ip=${server?.ipAddress} sshPort=${server?.sshPort} step=${server?.provisioningStep ?? ""} | job.status=${job?.status} progress=${job?.progress} step=${job?.step ?? ""} error=${job?.error ?? ""}`
    );
    if (job?.status === "DONE" || job?.status === "FAILED" || job?.status === "ERROR") {
      console.log(`TERMINAL job.status=${job.status}`);
      break;
    }
    if (server?.status === "RUNNING") {
      console.log("TERMINAL server.status=RUNNING");
      break;
    }
    if (server?.status === "ERROR") {
      console.log("TERMINAL server.status=ERROR");
      break;
    }
    await new Promise((r) => setTimeout(r, 30_000));
  }
  await db.$disconnect();
}
main().catch((e) => { console.error(e); process.exit(1); });

